mod support;
pub use video_kadr_backend::services::local_person;
use sha2::{Digest,Sha256};
use tokio_util::sync::CancellationToken;
use video_kadr_backend::{process_control::ProcessRuntime,services::{local_person_sequence::{self,Engine,Input},local_selfie,local_cutout}};
#[tokio::test]
#[ignore="requires actual pinned Selfie and ISNet models and native runtime"]
async fn actual_selfie_and_object_sequences_validate_every_frame_and_private_cleanup(){
 let dir=tempfile::tempdir().unwrap();let source=dir.path().join("frames.rgba");let pixels:Vec<u8>=(0..2).flat_map(|frame|(0..37*23).flat_map(move|p|[((p*17+frame*31)%256)as u8,((p*37)%256)as u8,((p+frame*89)%256)as u8,(p%256)as u8])).collect();std::fs::write(&source,&pixels).unwrap();let hash=format!("{:x}",Sha256::digest(&pixels));
 let exe=std::env::var("VIDEO_KADR_TEST_ENHANCE_BIN").unwrap();let ort=std::env::var("VIDEO_KADR_TEST_CHATTERBOX_LIBRARY").unwrap();let selfie=local_selfie::Config{executable:exe.clone().into(),model:std::env::var("VIDEO_KADR_TEST_SELFIE_MODEL").unwrap().into(),runtime_library:ort.clone().into()};let object=local_cutout::Config{executable:exe.into(),model:std::env::var("VIDEO_KADR_TEST_OBJECT_MODEL").unwrap().into(),runtime_library:ort.into()};let cancel=CancellationToken::new();let(tx,_rx)=tokio::sync::mpsc::unbounded_channel();let runtime=ProcessRuntime::local_default();
 let which=|name:&str|{let output=std::process::Command::new("which").arg(name).output().unwrap();assert!(output.status.success());std::path::PathBuf::from(String::from_utf8(output.stdout).unwrap().trim())};let ffmpeg=which("ffmpeg");let ffprobe=which("ffprobe");let video=dir.path().join("input.mkv");let encoded=std::process::Command::new(&ffmpeg).args(["-nostdin","-v","error","-f","rawvideo","-pix_fmt","rgba","-s","37x23","-r","10","-i"]).arg(&source).args(["-frames:v","2","-c:v","ffv1","-pix_fmt","bgra"]).arg(&video).output().unwrap();assert!(encoded.status.success(),"{}",String::from_utf8_lossy(&encoded.stderr));let video_hash=format!("{:x}",Sha256::digest(std::fs::read(&video).unwrap()));
 let(state,_state_dir)=support::make_state(true,false).await;std::fs::copy(&video,state.storage.join("sources/raw.mkv")).unwrap();assert!(state.library.add(video_kadr_backend::library::MediaEntry::from_result("source",&serde_json::json!({"id":"raw","filename":"raw.mkv","url":"/files/sources/raw.mkv","mediaType":"video","width":37,"height":23}))).await);let space=state.db.create_space("owner","Model caches").await.unwrap();let mut composition=video_kadr_backend::domain::composition::Composition::new(Default::default());let descriptor:video_kadr_backend::domain::composition::CompositionSource=serde_json::from_value(serde_json::json!({"id":"raw","kind":"video","durationTicks":200000,"width":37,"height":23,"hasAudio":false})).unwrap();composition.sources.insert(descriptor.id.clone(),descriptor);let project=state.db.create_space_composition_project("Model caches",&serde_json::to_value(composition).unwrap(),&["raw".into()],"owner",&space.id).await.unwrap();let mut registered=vec![];
 for(engine,name,edge,model_hash)in [(Engine::Selfie(&selfie),"selfie",256,"3241ac4ad8aa35bdaf33946776db29f7c283a413aa0b0dacb9483594b4531aad"),(Engine::Object(&object),"object",512,"60920e99c45464f2ba57bee2ad08c919a52bbf852739e96947fbb4358c0d964a")]{
  let output=dir.path().join(format!("{name}.rgba"));let masks=dir.path().join(format!("{name}.masks"));
  let metadata=local_person_sequence::segment_with_engine(&runtime,engine,Input{source:&source,source_hash:&hash,mask_destination:Some(&masks),width:37,height:23,frames:2},&output,&cancel,std::time::Duration::from_secs(120),&tx).await.unwrap();assert_eq!(metadata.schema_version,10);assert_eq!((metadata.width,metadata.height,metadata.frames),(37,23,2));assert_eq!((metadata.mask_width,metadata.mask_height),(edge,edge));assert_eq!(metadata.source_hash,hash);assert_eq!(metadata.model_hash,model_hash);assert_eq!(metadata.bytes,pixels.len()as u64);assert_eq!(metadata.mask_bytes,2*u64::from(edge).pow(2));assert_eq!(std::fs::metadata(&output).unwrap().len(),pixels.len()as u64);let planes=std::fs::read(&masks).unwrap();assert_eq!(format!("{:x}",Sha256::digest(&planes)),metadata.mask_hash);assert_eq!(planes.chunks_exact((edge*edge)as usize).filter(|mask|mask.iter().all(|v|*v<10)).count()as u64,metadata.blank_frames);
  let rejected=dir.path().join(format!("{name}-bad.rgba"));assert!(local_person_sequence::segment_with_engine(&runtime,engine,Input{source:&source,source_hash:"wrong",mask_destination:None,width:37,height:23,frames:2},&rejected,&cancel,std::time::Duration::from_secs(10),&tx).await.is_err());assert!(!rejected.exists());
  use video_kadr_backend::services::{concat_video_analysis::{RunCache,PublishedCache},local_enhance_video::Tools};
  let mut cache=RunCache::new_for_model(video_hash.clone(),metadata.runtime_hash.clone(),model_hash.into()).unwrap();let filled=cache.fill_missing_with_engine(&runtime,Tools{ffmpeg:&ffmpeg,ffprobe:&ffprobe},engine,&video,&[(0.,0.1)],dir.path(),4*1024*1024,&cancel,std::time::Duration::from_secs(120),&tx).await.unwrap();assert_eq!((filled.analysed_runs,filled.analysed_frames),(1,2));let identity=cache.identity().unwrap();
  let wrong=if name=="selfie"{Engine::Object(&object)}else{Engine::Selfie(&selfie)};let error=cache.fill_missing_with_engine(&runtime,Tools{ffmpeg:&ffmpeg,ffprobe:&ffprobe},wrong,&video,&[],dir.path(),4*1024*1024,&cancel,std::time::Duration::from_secs(30),&tx).await.unwrap_err();assert!(error.to_string().contains("model family"));assert!(cache.timeline().unwrap().missing_runs(&[(0.,0.1)]).unwrap().is_empty());
  video_kadr_backend::handlers::concat_video_cache::publish(&state,"owner",&project.id,"raw",project.revision,&mut cache,&cancel).await.unwrap();let restored=video_kadr_backend::handlers::concat_video_cache::restore_for_model(&state,"owner",&project.id,"raw",project.revision,&metadata.runtime_hash,model_hash,&cancel).await.unwrap().unwrap();assert_eq!(restored.identity().unwrap(),identity);assert!(video_kadr_backend::handlers::concat_video_cache::restore(&state,"owner",&project.id,"raw",project.revision,&metadata.runtime_hash,&cancel).await.unwrap().is_none());assert!(video_kadr_backend::handlers::concat_video_cache::restore_for_model(&state,"outsider",&project.id,"raw",project.revision,&metadata.runtime_hash,model_hash,&cancel).await.is_err());registered.push((model_hash.to_owned(),metadata.runtime_hash.clone(),identity.clone()));
  let receipt=cache.publish(dir.path(),4*1024*1024,&cancel).await.unwrap();assert_eq!(receipt.model_hash,model_hash);drop(cache);let mut restored=RunCache::restore(&receipt,4*1024*1024,&cancel).await.unwrap();assert_eq!(restored.identity().unwrap(),identity);assert_eq!(restored.timeline().unwrap().nearest_millis(0.1).unwrap(),Some(100));let mut picture=video_kadr_backend::domain::group_surface::GroupSurface{width:37,height:23,rgba:pixels[37*23*4..].to_vec()};restored.apply_decoded(&mut picture,100000,&cancel).unwrap();for(actual,input)in picture.rgba.chunks_exact(4).zip(pixels[37*23*4..].chunks_exact(4)){assert_eq!(actual[..3],input[..3]);}drop(restored);
  let wrong_receipt=PublishedCache{directory:receipt.directory.clone(),manifest_hash:receipt.manifest_hash.clone(),video_hash:receipt.video_hash.clone(),runtime_hash:receipt.runtime_hash.clone(),model_hash:video_kadr_backend::services::local_person::MODEL_HASH.into()};assert!(RunCache::restore(&wrong_receipt,4*1024*1024,&cancel).await.is_err());assert!(receipt.directory.is_dir());std::fs::remove_dir_all(receipt.directory).unwrap();

 }
 let mut reopened=state.clone();reopened.db=std::sync::Arc::new(video_kadr_backend::db::Db::open(&state.storage).await.unwrap());for(model,runtime,identity)in registered{let restored=video_kadr_backend::handlers::concat_video_cache::restore_for_model(&reopened,"owner",&project.id,"raw",project.revision,&runtime,&model,&cancel).await.unwrap().unwrap();assert_eq!(restored.identity().unwrap(),identity);}
 assert!(std::fs::read_dir(dir.path()).unwrap().all(|entry|!entry.unwrap().file_type().unwrap().is_dir()));
}
